    [2040] = "從死亡礦坑中帶回小型高能發動機，將其帶給暴風城矮人區中的沉默的舒尼。",
    [2198] = "找到破碎的項鏈的來源，從而瞭解其潛在的價值。",
    [2199] = "給鐵爐堡的塔瓦斯德·基瑟爾帶去五塊銀錠。",
    [2200] = "去奧達曼尋找塔瓦斯的魔法項鏈，被殺的聖騎士是最後一個拿著它的人。",
    [2201] = "在奧達曼尋找紅寶石、藍寶石和黃寶石的下落。找到它們之後，通過塔瓦斯德給你的占卜之瓶和他進行聯繫。",
    [2202] = "收集12顆紫色蘑菇，把它們交給卡加斯的加卡爾。",
    [2204] = "從奧達曼最強大的石人身上獲得能量源，然後將其交給鐵爐堡的塔瓦斯德。",
    [2240] = "閱讀巴爾洛戈的日記，探索密室，然後向鐵爐堡的勘察員塔伯斯·雷矛彙報。",
    [2278] = "和石頭守護者交談，從他那裡瞭解更多古代的知識。一旦你瞭解到了所有的內容之後就啟動諾甘農圓盤。",
    [2279] = "把迷你版的諾甘農圓盤帶到鐵爐堡的探險者協會去。",
    [2280] = "把迷你版的諾甘農圓盤帶到雷霆崖的賢者那裡。",
    [2283] = "在奧達曼挖掘場中尋找一條珍貴的項鏈，然後將其交給奧格瑪的德蘭·杜佛斯。項鏈有可能已經損壞。",
    [2284] = "在奧達曼裡找尋寶石的線索。",
    [2318] = "在荒蕪之地的卡加斯哨所裡尋找一個可以幫你翻譯聖騎士日記的人。",
    [2338] = "將項鏈借給加卡爾。作為交換，他將幫你翻譯日記。",
    [2339] = "從奧達曼找回項鏈上的所有三塊寶石和能量源，然後把它們交給卡加斯的加卡爾。$B$B紅寶石被藏在暗影矮人層層設防的地區。$B$B黃寶石藏在石齶怪活動地區的一個甕中。$B$B藍寶石在格瑞姆洛克手中，他是石齶怪的領袖。$B$B能量源可能在奧達曼的某個最強生物的手中。",
    [2340] = "把項鏈和寶石送到奧格瑪的德蘭·杜佛斯那裡。",
    [2341] = "去卡加斯看看加卡爾是否成功了。",
    [2342] = "從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的派翠克·加瑞特。",
    [2359] = "偷取迪菲亞塔樓鑰匙，進入迪菲亞塔樓，看看暮色森林的箱子裡到底有什麼東西，然後向暴風城的馬迪亞斯·肖爾彙報。",
    [2360] = "去西部荒野和密探吉爾妮談話。",
    [2361] = "我很高興能給你這條項鏈，強大的$C。你對我的幫助是無價的，我為此對你表示萬分的感謝。請把它戴上吧，這是屬於你的榮耀，請在別人問及的時候告訴他們，是我製作了這條項鏈！$B$B另外，如果你證明這條項鏈根本沒有受到詛咒，那就更棒了。",
    [2398] = "在奧達曼找到巴爾洛戈。",
    [2418] = "給荒蕪之地的里格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。",
    [2439] = "把你的報酬憑證交給鐵爐堡銀行的丁尼塔·石衣。",
    [2440] = "把報酬憑證交給雷霆崖的貝娜·冰蹄。",
    [2458] = "到淤泥沼澤北邊的風險投資公司塔樓去，聯繫碎手氏族的臥底費蘇勒。$B$B看到塔樓之後，用信號槍發射信號，向工頭費蘇勒示意你已經到達。發出兩個閃光信號，然後使用碎手軍禮和工頭費蘇勒接頭。$B$B注意，這些步驟必須依次進行，因為費蘇勒會攻擊並幹掉任何他無法識別的人。",
    [2460] = "對著申蘇爾練習碎手軍禮。",
    [2478] = "從工頭希里克斯那裡偷出希里克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。$B$B殺掉大工頭普茲克·加里維克斯，取了他的首級，然後打開加里維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加里維克斯的頭顱交給奧格瑪的申蘇爾，等候進一步的指示。",
    [2479] = "到希爾斯布萊德丘陵的塔倫米爾去，把贊吉爾的藥劑樣品交給瑟爾格·希諾特。$B$B要去塔倫米爾，可以搭乘飛艇到幽暗城，然後沿著大路向南穿過銀松森林，直到希爾斯布萊德丘陵。跟著路標走！",
    [2480] = "等待瑟爾格·希諾特完成解藥。",
    [2607] = "到兵營的地窖裡去和道克·米希匹克斯談話。",
    [2608] = "用/lay指令躺下，接受道克·米希匹克斯的治療。如果他找不到病因，就找不到治療的方法。",
    [2609] = "給道克·米希匹克斯帶去一束普通野花、一隻鉛瓶，一根青銅管，最後還要一卷淡綠色絲線。伊提斯綜合症可不會不治而愈，年輕的$G先生:小姐;。",
    [2621] = "與斯通納德的分隊指揮官盧爾格談話。",
    [2622] = "與本戈爾談話。",
    [2623] = "取回酋長的命令，把它們還給部落英雄的靈魂。",
    [2681] = "解救九個拉瑟萊克的僕從、三個瑟溫妮的僕從、三個奧利斯塔的僕從和三個戈洛爾的僕從。完成任務後，回到部落英雄的靈魂這裡。",
    [2701] = "打開箱子，取走你的酬勞。",
    [2702] = "和桑德·裂蹄談話。",
    [2721] = "找到基利斯的下落。",
    [2743] = "回去見部落英雄的靈魂，將你的發現告訴他。",
    [2744] = "與艾薩拉的洛拉姆斯·薩里比迪斯談話。",
    [2745] = "與暴風城堡的泰里恩談話。",
    [2746] = "將3塊絲綢和2顆克拉拉的新鮮蘋果交給暴風城的泰里恩。",
    [2768] = "把探水棒交給加基森的首席工程師沙克斯·比格維茲。",
    [2770] = "把加茲瑞拉的鱗片交給閃光平原的維茲爾·銅栓。",
    [2783] = "與詛咒之地和悲傷沼澤交界處的部落英雄的靈魂談話。",
    [2784] = "聆聽部落英雄的靈魂講述他的故事。",
    [2801] = "聆聽部落英雄的靈魂講述他的故事。",
    [2846] = "將深淵皇冠交給塵泥沼澤的塔貝薩。",
    [2861] = "與塵泥沼澤的塔貝薩談話。",
    [2864] = "與加基森的特蘭雷克談話。",
    [2865] = "帶5個完整的聖甲蟲殼給加基森的特蘭雷克。",
    [2936] = "閱讀塞卡石板，瞭解枯木食人妖的蜘蛛之神的名字，然後回到加德林大師那裡。",
    [2983] = "去貧瘠之地找到卡納爾·菲斯。",
    [2984] = "去貧瘠之地找到卡納爾·菲斯。",
    [2985] = "找到貧瘠之地的水之先知伊斯倫。",
    [2986] = "找到貧瘠之地的水之先知伊斯倫。",
    [2991] = "將耐克魯姆的徽章交給詛咒之地的薩迪斯·格希德。",
    [3001] = "在棘齒城找到斯坦哈德·法爾杉。",
    [3042] = "收集20瓶食人妖調和劑，把它們交給加基森的特倫頓·輕錘。",
    [3141] = "聽洛拉姆斯·薩里比迪斯講述他的故事。",
    [3369] = "把噩夢碎片交給長者高地的哈繆爾·符文圖騰。",
    [3370] = "把噩夢碎片交給達納蘇斯的瑪斯雷·馭熊者。",
    [3373] = "把伊蘭尼庫斯精華放在精華之泉裡，精華之泉就在沉沒的神廟中，伊蘭尼庫斯的巢穴裡。",
    [3380] = "到塔納利斯找到瑪爾馮·瑞文斯克。",
    [3446] = "在悲傷沼澤的沉沒神廟中找到哈卡祭壇。",
    [3447] = "去沉沒的神廟，找出雕像群中隱藏的秘密。",
    [3504] = "把這封給阿格圖的密信交給艾薩拉的阿格圖·血拳。",
    [3505] = "殺死10個血精靈搜尋者和10個血精靈探測員，然後尋找大法師雷姆托里的營地。一旦你發現了營地，找出某個對她極為重要的東西，以用於激怒她，讓她與你戰鬥。",
    [3508] = "等待洛拉姆斯完成啟迪法術。",
    [3509] = "與艾薩拉的亞考羅克談一談。你應該在海邊搜索亞考蘭神殿。",
    [3510] = "殺掉赫塔拉，將染血的赫塔拉頭顱、破碎的赫塔拉頭顱和淤血的赫塔拉頭顱交給亞考羅克。",
    [3511] = "將調劑交給洛拉姆斯·薩里比迪斯。",
    [3520] = "到菲拉斯捕獲3個尖叫者的靈魂，然後回到熱砂港的葉金亞那裡。",
    [3527] = "將第一塊和第二塊摩沙魯石板交給塔納利斯的葉基亞。",
    [3528] = "將裝滿的哈卡之卵交給塔納利斯的葉基亞。",
    [3602] = "在艾薩拉南部收集20塊艾薩拉晶體。你可以使用地獄犬協助尋找一些隱藏的礦脈。$B$B任務完成之後就回到洛拉姆斯那裡去。",
    [3621] = "把貨物交給荊棘谷的加爾文。",
    [3625] = "等待加爾文為你鍛造武器。",
    [3626] = "回到部落英雄的靈魂那裡。",
    [3627] = "殺掉毀滅者戈洛爾、瑟溫妮，以及大法師奧利斯塔。從他們到屍體上拿到戈洛爾的護符、瑟溫妮的護符和奧利斯塔的護符。$B$B記住使用你的魔化艾薩拉水晶武器來削弱他們，否則他們是無法被殺死的——你必須小心謹慎地使用你的武器……",
    [3628] = "消滅污染者拉瑟萊克，將污染者之角交給部落英雄的靈魂。另外你還要把污染者防護結界交給他，這樣部落英雄的靈魂就可以消滅它，以避免它落入邪惡勢力之手。",
    [3631] = "與貧瘠之地棘齒城的斯坦哈德·法爾杉談話。",
    [3701] = "到燃燒平原的索瑞森廢墟中去，從索瑞森聖物上搜集資訊。當你收集到足夠的資訊之後，就回到皇家歷史學家阿克瑟努斯那裡。",
    [3702] = "聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。",
    [3783] = "為永望鎮的烏米收集10張厚雪人毛皮。",
    [3801] = "如果你想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談話。",
    [3802] = "殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。",
    [3844] = "在池塘附近查找與擱淺的小艇有關的線索。",
    [3845] = "查看袋子裡的東西，然後將它們交給物主。",
    [3903] = "與米莉·奧斯沃斯談話。",
    [3904] = "收集8箱米莉的葡萄，把它們交給北郡修道院的米莉·奧斯沃斯。",
    [3907] = "進入黑石深淵並找到伊森迪奧斯。殺掉它，然後把你找到的資訊彙報給桑德哈特。",
    [3908] = "把林克的劍交給冬泉谷的多諾瓦·雪山。",
    [3909] = "去菲拉斯找格雷甘·山酒。從他那裡問到獲取視靈藥劑的方法，然後向冬泉谷的多諾瓦·雪山覆命。",
    [3912] = "在加基森鎮外的墓地中使用視靈藥劑，然後按照多諾瓦的指示找到加里楊。",
    [3913] = "復活，然後尋找加里楊讓你去找的那塊墓碑。",
    [3914] = "把林克的強化之劍交給安戈洛環形山的林克。",
    [3941] = "到馬紹爾營地那裡的山洞中去找科琳。",
    [3942] = "到費伍德森林去找艾瑞丹·藍風。",
    [3961] = "把亞奎門塔斯的銀圖騰交給馬紹爾營地裡的林克。",
    [3962] = "到馬紹爾營地南邊的火羽山去。$B$B找到火焰使者，並使用圖騰除掉它的防護光環。在擊敗它之後從洞中取得金色火焰。",
    [3981] = "在黑石深淵裡找到指揮官哥沙克。$B$B在那幅草圖上畫著的是一個鐵欄後面的獸人，也許你應該到某個類似監獄的地方去找找看。",
    [3982] = "保護哥沙克。",
    [4001] = "與卡蘭·巨錘談一談，收集關於綁架公主鐵爐堡公主茉艾拉·銅鬚這一事件的情報。將情報回饋給奧格瑪城裡的索爾。$B$B哥沙克提到過卡蘭被關在附近的某個牢房中。",
    [4002] = "如果你準備好要接受索爾所安排的任務，就去找他談話。",
    [4003] = "殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅鬚從他的邪惡詛咒中拯救出來。",
    [4004] = "向索爾報告！",
    [4005] = "把阿奎爾之書、銀爪，還有鐵樹心帶到塔納利斯。$B$B用這本書召喚亞奎門塔斯。$B$B當你完成圖騰之後，把它帶給在馬紹爾營地的科琳。",
    [4024] = "到黑石深淵去殺掉貝爾加。$B$B你只知道這個巨型怪物住在黑石深淵的最深處。記住你要使用特殊的黑龍皮從貝爾加的屍體上採集烈焰精華。$B$B將你採集到的烈焰精華交給塞勒斯·薩雷芬圖斯。",
    [4063] = "找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。你還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。",
    [4081] = "到黑石深淵去消滅那些邪惡的侵略者！$B$B指揮官高圖斯要你去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去找他。",
    [4082] = "到黑石深淵去消滅那些邪惡的侵略者！$B$B高圖斯軍閥要你殺死10個鐵怒醫師,、10個鐵怒士兵和10個鐵怒軍官。完成任務之後回去向他覆命。",
    [4083] = "Requirements:$B- 紅寶石 x 2$B- 金錠 x 20$B- 真銀錠 x 10",
    [4084] = "為費伍德森林的艾瑞丹·藍風收集11隻銀爪和1顆鐵樹之心。",
    [4121] = "押送你的囚犯格拉克·洛克魯布。穿過燃燒平原和黑石山脈，一直走到灼熱峽谷。$B$B雷克斯洛特曾經告訴過你，他會讓他的人等在黑石山脈的另外一邊準備接收格拉克。$B$B另外，你還要把瑟銀鐐銬一併還給雷克斯洛特。",
    [4122] = "到燃燒平原去找到格拉克·洛克魯布。你回憶起雷克斯洛特曾經提起過，格拉克應該是在一座大型的黑石要塞中。$B$B當你找到格拉克·洛克魯布之後，用瑟銀鐐銬把他銬起來，然後將其帶回灼熱峽谷。雷克斯洛特會讓他的部下等在那裡接應你。",
    [4123] = "把山脈之心交給燃燒平原的麥克斯沃特·尤柏格林。",
    [4124] = "和羽月要塞的基恩諾·火花談話。",
    [4125] = "找到信差的小船，你應該在菲拉斯的南部海岸線上展開搜索。",
    [4126] = "把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。",
    [4127] = "回到羽月要塞，給基恩諾·火花看看你找到的這把被丟棄的小刀。",
    [4128] = "和拉格納·雷酒談談。",
    [4129] = "把被丟棄的小刀交給羽月要塞的奎恩提斯。",
    [4130] = "和羽月要塞的基恩諾·火花談話。",
    [4131] = "在菲拉斯南部地區的木爪豺狼人營地裡尋找信差的下落或者信差的物品。",
    [4132] = "到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯覆命。",
    [4133] = "與卡加斯的暗法師薇薇安·拉格雷談話。",
    [4134] = "把遺失的雷酒秘方交給卡加斯的薇薇安·拉格雷。",
    [4135] = "現在你已經知道了拉斯卡爾的去向，那麼你最好到痛苦深淵去尋找他，或者至少是他的屍體。根據便箋上的資訊，那個地方應該在木爪豺狼人營地的南邊。",
    [4136] = "把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。",
    [4182] = "殺掉15條黑色小龍、10條黑色龍人和1條黑色幼龍。當你完成任務之後就向赫林迪斯·河角回報。",
    [4183] = "把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。",
    [4184] = "到暴風城去把所羅門的求援信交給伯瓦爾·弗塔根公爵。$B$B伯瓦爾在暴風要塞裡。",
    [4185] = "與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。",
    [4186] = "把伯瓦爾的命令交給湖畔鎮的所羅門鎮長。",
    [4201] = "將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。",
    [4223] = "和燃燒平原的麥克斯韋爾元帥談話。",
    [4224] = "和狼狽不堪的約翰談談來瞭解溫德索爾元帥的命運，然後回到麥克斯韋爾元帥那裡。$B$B你想起麥克斯韋爾元帥說過他在一個北面的洞穴那裡。",
    [4241] = "到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。$B$B狼狽不堪的約翰曾告訴你說溫德索爾被關進了一個監獄。",
    [4242] = "把這個壞消息傳達給麥克斯韋爾元帥。",
    [4263] = "在黑石深淵裡找到伊森迪奧斯，然後把他幹掉！",
    [4264] = "溫德索爾元帥也許會對你手中的東西感興趣。畢竟，希望還沒有被完全扼殺。",
    [4265] = "將拉斯卡爾安全護送到祖卡什蟲巢外。$B$B回到羽月要塞的基恩諾·火花那兒，告訴他拉斯卡爾還活著，且狀況良好。",
    [4266] = "與羽月要塞的珊蒂斯·羽月談話。",
    [4267] = "把拉斯卡爾的報告交給達納蘇斯的格拉希娜·靈風。",
    [4281] = "將未遞送的包裹交給薩蘭納爾驛站的法芬德爾。",
    [4282] = "找回溫德索爾元帥遺失的情報。$B$B溫德索爾元帥確信那些情報在安格弗將軍和傀儡元帥阿格曼奇的手裡。",
    [4286] = "到黑石深淵去找到20個黑鐵挎包。當你完成任務之後，回到奧拉留斯那裡覆命。你認為黑石深淵裡的黑鐵矮人應該會有這些黑鐵挎包。",
    [4322] = "幫助溫德索爾元帥拿回他的裝備並救出他的朋友。當你成功之後就回去向麥克斯韋爾元帥覆命。",
    [4324] = "與燃燒平原的尤卡·斯庫比格特談話。",
    [4341] = "去黑石深淵找到卡蘭·巨錘。$B$B國王提到卡蘭在那裡負責看守囚犯——也許你應該在監獄附近尋找他。",
    [4342] = "聽卡蘭·巨錘說他的故事。",
    [4361] = "回到鐵爐堡，把這個壞消息帶給國王麥格尼·銅鬚。",
    [4362] = "回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅鬚。",
    [4363] = "回到鐵爐堡去，與國王麥格尼·銅鬚談話。",
    [4487] = "與棘齒城的斯坦哈德·法爾杉談話。",
    [4488] = "與棘齒城的斯坦哈德·法爾杉談話。",
    [4489] = "與棘齒城的斯坦哈德·法爾杉談話。",
    [4490] = "與棘齒城的斯坦哈德·法爾杉談話，學習召喚地獄戰馬的能力。",
    [4701] = "到黑石塔去摧毀那裡的座狼源頭。當你離開的時候，赫林迪斯喊出了一個名字：哈雷肯。這個詞就是獸人語中「座狼」的意思。",
    [4724] = "殺死血斧座狼的領袖，哈雷肯。",
    [4729] = "到黑石塔去找到小血斧座狼。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的小座狼交給基布雷爾。",
    [4734] = "在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。",
    [4735] = "將電動採集模組和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。",
    [4742] = "找到三塊命令寶石：燃棘寶鑽、尖石寶鑽和血斧寶鑽。把它們和原始晉升印章一起交給維埃蘭。$B$B可能攜帶者三塊寶石的將軍是：燃棘氏族的指揮官沃恩、尖石氏族的歐莫克大王，以及血斧氏族的維姆薩拉克。",
    [4743] = "到塵泥沼澤中的巨龍沼澤去。找到上古老龍艾博斯塔夫，對他發起無情的攻擊，直到他的意志被摧毀。$B$B此時，你必須儘快將未鑄造的晉升印章放在這條龍面前，並使用龍力寶珠控制他的軀體，強迫他將黑龍的烈焰噴向未鑄造的晉升印章！",
    [4764] = "將末日扣環交給燃燒平原的瑪亞拉·布萊特文。",
    [4765] = "將瑞治維爾的箱子交給暴風城的雷明頓·瑞治維爾。",
    [4766] = "與燃燒平原的瑪亞拉·布萊特文談話。",
    [4768] = "將黑暗石板交給卡加斯的暗法師薇薇安·拉格雷。",
    [4769] = "與卡加斯的暗法師薇薇安·拉格雷談話。",
    [4771] = "將黎明先鋒放在通靈學院的觀察室裡。打敗維克圖斯,然後回到貝蒂娜·比格辛克那裡去。",
    [4787] = "將遠古之卵交給塔納利斯的葉基亞。",
    [4788] = "將第五塊和第六塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。",
    [4862] = "到黑石塔去為基布雷爾收集15枚尖塔蜘蛛卵。$B$B聽說那些蜘蛛周圍有許多這樣的卵。",
    [4866] = "你可以在黑石塔的中心地帶找到煙網蛛后。與她戰鬥，讓她在你體內注入毒汁。如果你有能力的話，就殺死她吧。當你中毒之後，回到狼狽不堪的約翰那兒，他會從你的身體裡抽取這些「蛛后的乳汁」。",
    [4867] = "閱讀瓦羅什的卷軸。將瓦羅什的魔精交給他。",
    [4903] = "殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石文件，然後向卡加斯的軍官高圖斯彙報。",
    [4907] = "與丁奇·斯迪波爾談話。",
    [4921] = "找到曼寇里克的妻子，然後回到十字路口找他。",
    [4941] = "和奧格瑪的伊崔格談話。討論完畢後，諮詢索爾的意見。$B$B你回憶起曾在索爾的大廳中見過伊崔格。",
    [4974] = "去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑪。",
    [4981] = "到黑石塔去查明比修的下落。",
    [4982] = "找到比修的裝置並把它們還給她。你記得她說過她把裝置藏在城市的最底層。",
    [4983] = "把比修的偵查報告交給卡加斯的雷克斯洛特。",
    [5001] = "找到比修的裝置並且交還給她。祝你好運！",
    [5002] = "把比修的消息帶去給在燃燒平原的麥斯威爾元帥。",
    [5047] = "與永望鎮的瑪雷弗斯·暗錘談話。",
    [5061] = "回到達納蘇斯，讓瑪斯雷·馭熊者看看你的海獅墜飾。",
    [5065] = "把第三塊和第四塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。",
    [5081] = "到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處覆命。",
    [5089] = "把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。",
    [5096] = "到血色十字軍建在費爾斯通農場和達爾松之淚之間的營地去，摧毀他們的指揮帳篷。$B$B將天譴軍團的戰旗插在營地中，然後回到西瘟疫之地亡靈壁壘的高級執行官德靈頓那兒。",
    [5097] = "使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。$B$B在做完了標記之後，將信號火炬還給西瘟疫之地冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。",
    [5098] = "使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。$B$B在做完了標記之後，將信號火炬還給西瘟疫之地亡靈壁壘的高級執行官德靈頓。",
    [5102] = "去黑石塔殺掉達基薩斯將軍。當任務完成之後回去找麥斯威爾指揮官。",
    [5122] = "這個小教堂給了我抵抗內心中的腐化力量。如果離開這裡，我就會變成一個死亡騎士。但是有一枚獎章，信仰獎章，它可以給予我離開這裡所需的力量。$B$B$N，請幫我拿回這枚獎章。它被狂熱的瑪洛爾看護著，他是血色十字軍的一員，居住在西斯坦索姆的血色十字軍堡壘深處。",
    [5125] = "$N，我快要死了……但我的靈魂得救了。為此，我欠你的遠非言語所能表達。請收下這個……繼續戰鬥吧，勇敢的$C！",
    [5127] = "到黑石塔去找到古拉魯克。殺死他，然後用血污長矛刺入他的屍體。當他的靈魂被吸幹後，這支矛就會成為穿魂長矛。$B$B你還必須找到未鑄造的符文覆飾胸甲。$B$B將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。",
    [5142] = "找尋潘蜜拉·雷德帕斯。",
    [5149] = "找到帕米拉的洋娃娃。",
    [5152] = "與安多哈爾廢墟南邊的瑪萊恩談話。",
    [5153] = "把約瑟夫的結婚戒指交給安多哈爾的克羅米。",
    [5154] = "把《達隆郡的歷史》交給安多哈爾的克羅米。",
    [5160] = "到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。",
    [5163] = "帶著烏米的機械雪人去嚇唬她的朋友：$B$B永望鎮的萊加奇（冬泉谷）、加基森的斯普琳科（塔納利斯），還有馬紹爾營地的奎克希爾（安戈洛環形山）。$B$B當你完成任務之後，把機械雪人還給烏米。",
    [5168] = "把達維的聖契和雷德帕斯之盾交給卡林·雷德帕斯。",
    [5181] = "將霍古斯的顱骨和馬杜克的破碎之劍交給聖光之願禮拜堂的卡林·雷德帕斯。",
    [5206] = "把5個共鳴顱骨和神秘水晶交給東瘟疫之地的卡林·雷德帕斯。",
    [5210] = "將《達隆鎮全史》交給東瘟疫之地的卡林·雷德帕斯。",
    [5211] = "釋放15個達隆郡居民的靈魂，然後返回卡林·雷德帕斯身邊。",
    [5212] = "從斯坦索姆找回20個瘟疫肉塊，並把它們交給貝蒂娜·比格辛克。你覺得斯坦索姆中的生物都不大可能長著肉。",
    [5213] = "到斯坦索姆去探索那裡的通靈塔。找到新的天譴軍團檔案，把它交給貝蒂娜·比格辛克。",
    [5214] = "找到艾茲拉‧格里姆在斯坦索姆的煙草店，並從中找回一盒格里姆的特級煙草，把它交給煙鬼拉魯恩。",
    [5241] = "找到卡林·瑞德巴思。",
    [5243] = "到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當你找到足夠的聖水之後就回去向萊尼德·巴薩羅梅覆命。",
    [5251] = "在斯坦索姆城中找到血色十字軍的文件管理員加爾福特，殺掉他，然後燒毀血色十字軍文獻。",
    [5262] = "將巴納札爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。",
    [5263] = "到斯坦索姆去殺掉瑞文戴爾男爵，把他的頭顱交給尼古拉斯·瑟倫霍夫公爵。",
    [5282] = "對斯坦索姆的鬼魂使用伊根的衝擊器。當那些永不安息的靈魂掙脫他們的外殼時，再次使用伊根的衝擊器——他們就可以獲得自由了！$B$B解放15個永不安息的靈魂，然後回到伊根那裡去。",
    [5341] = "到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。",
    [5342] = "到冰風營地——聯盟的領地——去暗殺維爾頓·巴羅夫。把他的腦袋交給阿萊克斯·巴羅夫。$B$B要多加小心，聯盟也許對維爾頓執行了嚴密的保護。",
    [5343] = "到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。",
    [5344] = "去亡靈壁壘——部落的領地——去暗殺阿萊克斯·巴羅夫。把他的腦袋交給維爾頓·巴羅夫。$B$B要小心，部落也許對阿萊克斯執行了嚴密的保護。",
    [5382] = "在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒毀艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。",
    [5383] = "将恐惧之袋交给凯尔达隆的艾瓦·萨克霍夫。",
    [5384] = "帶著無辜者之血回到通靈學院，將它放在門廊的火盆下方，基爾圖諾斯會前來吞噬你的靈魂。$B$B勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。",
    [5461] = "到阿拉希高地的激流堡遺跡裡面尋找巫妖生前的遺物。如果你能找到這樣的東西，就把它交給馬杜克鎮長。",
    [5462] = "到東瘟疫之地的聖光之願禮拜堂去找到萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他你收集到的情報。",
    [5463] = "到斯坦索姆城裡去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。",
    [5464] = "把禁錮靈魂的遺物交給東瘟疫之地的萊尼德·巴薩羅梅。",
    [5465] = "回到凱爾達隆的馬杜克鎮長那裡，把禁錮靈魂的遺物交給他。",
    [5466] = "在通靈學院裡找到萊斯·霜語。當你找到他之後，使用禁錮靈魂的遺物破除其不死族的外殼。如果你成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。",
    [5514] = "把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。",
    [5515] = "在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。",
    [5518] = "把4份符文布卷、8塊硬甲皮、2卷符文線和一份巨魔鞣酸交給諾特·希姆加克。他現在被拴在厄運之槌的戈多克巨魔那邊。",
    [5525] = "我說的是戈多克鐐銬鑰匙——好吧，那些胖傢伙是這麼叫它的。任何巨魔都有可能拿著這把鑰匙，不過我不清楚到底誰拿著它。沒准那些衛兵是負責看管鑰匙的……$B$B啊呀，我到底在想什麼？你已經拿到鑰匙了，對吧？",
    [5528] = "你是頭兒，可以喝我的酒！讓你精神煥發！都是好酒，頭兒……你嘗嘗，告訴克雷格！",
    [5529] = "殺掉20隻瘟疫幼龍，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。",
    [5531] = "將冰凍的龍蛋交給貝蒂娜·比格辛克。",
    [5533] = "和西瘟疫之地冰風崗的化學家阿爾比頓談話。",
    [5537] = "將15塊骷髏碎片交給西瘟疫之地冰風崗的化學家阿爾比頓。",
    [5538] = "把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。",
    [5582] = "把健康的龍鱗交給東瘟疫之地聖光之願禮拜堂中的貝蒂娜·比格辛克。",
    [5601] = "在達隆郡裡找到帕米拉·雷德帕斯。",
    [5721] = "將聖物包裹放在達隆郡的廣場中。$B$B在霍古斯死亡之前，達維必須存活。$B$B在雷德帕斯隊長墮落之前保證他存活。$B$B擊敗墮落的雷德帕斯。$B$B當約瑟夫·雷德帕斯出現在廣場中時，與他的靈魂進行交談，然後回到帕米拉的家中去找帕米拉。",
    [5742] = "聽聽提里恩·弗丁要說什麼。",
    [5762] = "將克拉維爾的箱子送到荊棘谷的赫米特·奈辛瓦里那裡。",
    [5763] = "將魯恩的科多獸角送到荊棘谷的赫米特·奈辛瓦里那裡。",
    [5781] = "到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提里恩·弗丁那裡。",
    [5801] = "把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。$B$B把未完工的骷髏鑰匙交給西瘟疫之地冰風崗的化學家阿爾比頓。",
    [5802] = "把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。$B$B把未完工的骷髏鑰匙交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。",
    [5803] = "殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地冰風崗的化學家阿爾比頓。",
    [5804] = "摧毀安多哈爾的4顆天災召喚水晶來召喚阿拉基。殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。",
    [5845] = "到東瘟疫之地東北部的北谷去，找到失落榮耀的象徵。完成目標之後向提里恩·弗丁覆命。",
    [5846] = "到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。",
    [5848] = "到瘟疫之地北部的斯坦索姆去。你可以在血色十字軍堡壘中找到「愛與家庭」這幅畫，它被隱藏在另一幅描繪兩個月亮的畫之後。$B$B把這幅畫還給提里恩·弗丁。",
    [5861] = "到瘟疫之地南部的烏瑟之墓去，將提里恩的禮物交給巫女米蘭達。",
    [5862] = "和巫女米蘭達交談以獲得血色幻象的效果。在血色幻象的掩護下深入壁爐谷，將提里恩的禮物交給大領主泰蘭·弗丁。$B$B壁爐谷在北方，泰蘭應該在瑪登霍爾德城堡裡面。",
    [5921] = "使用法術「傳送：月光林地」抵達月光林地，在那裡與永夜港的德迪利特·星焰談話。",
    [5922] = "使用法術「傳送：月光林地」前去月光林地，在那裡與永夜港的德迪利特·星焰談話。",
    [5923] = "與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。",
    [5924] = "與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。",
    [5925] = "與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。",
    [5926] = "與雷霆崖長者高地上的圖拉克·符文圖騰談話。",
    [5927] = "與雷霆崖長者高地上的圖拉克·符文圖騰談話。",
    [5928] = "與雷霆崖長者高地上的圖拉克·符文圖騰談話。",
    [5929] = "到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。",
    [5930] = "到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。",
    [5931] = "回到達納蘇斯，與塞納里奧區的瑪斯雷·馭熊者談話。",
    [5932] = "回到雷霆崖，與長者高地的圖拉克·符文圖騰談話。",
    [5941] = "將一包聖物交給安多哈爾的克羅米。",
    [5942] = "用約瑟夫的鑰匙打開約瑟夫的箱子。",
    [5944] = "護送泰蘭·弗丁走出壁爐谷。",
    [6001] = "使用奧伯丁的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。$B$B任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談話。",
    [6002] = "使用莫高雷與貧瘠之地交界處的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。$B$B任務完成之後，與雷霆崖的圖拉克·符文圖騰談話。",
    [6004] = "殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。",
    [6023] = "殺掉獵人萊德雷和騎士杜爾根，然後向西瘟疫之地的科爾斯塔·迪普沙東覆命。",
    [6025] = "進入壁爐谷並找一處高地，你可以在那裡觀察整個城鎮並估算血色十字軍的兵力，然後向西瘟疫之地的科爾斯塔·迪普沙東回報。",
    [6061] = "使用馴獸棒馴服成年陸行鳥。練習你的技能，然後將馴獸棒還給血蹄村的雅文·刺鬃。",
    [6062] = "使用馴獸棒馴服可怕的雜斑野豬。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。",
    [6063] = "使用馴獸棒馴服樹林潛伏者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。",
    [6064] = "使用馴獸棒馴服大型峭壁野豬。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。",
    [6065] = "與血蹄村的雅文·刺鬃談話。",
    [6066] = "與血蹄村的雅文·刺鬃談話。",
    [6067] = "與血蹄村的雅文·刺鬃談話。",
    [6068] = "與剃刀嶺的索塔爾談話。",
    [6069] = "與剃刀嶺的索塔爾談話。",
    [6070] = "與剃刀嶺的索塔爾談話。",
    [6071] = "與多蘭納爾的達札拉談話。",
    [6072] = "與多蘭納爾的達札拉談話。",
    [6073] = "與多蘭納爾的達札拉談話。",
    [6074] = "與卡拉諾斯的格瑞夫談話。",
    [6075] = "與卡拉諾斯的格瑞夫談話。",
    [6076] = "與卡拉諾斯的格瑞夫談話。",
    [6081] = "與奧格瑪的奧瑪克談話。",
    [6082] = "使用馴獸棒馴服硬甲蠍。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。",
    [6083] = "使用馴獸棒馴服海浪蟹。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。",
    [6084] = "使用馴獸棒馴服雪豹。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。",
    [6085] = "使用馴服獸棒馴服一頭冰爪熊。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。",
    [6086] = "與鐵爐堡的貝莉亞·雷岩談話。",
    [6087] = "使用馴獸棒馴服一隻草原捕食者。練習你的技能，然後將馴獸棒還給血蹄村的雅文·刺鬃。",
    [6088] = "使用馴獸棒馴服一隻猛鷲。練習你的技能，然後將馴服法杖交還給血蹄村的雅文·刺鬃。",
    [6089] = "與雷霆崖獵人高地的浩特·雷角談話。",
    [6101] = "使用馴獸棒馴服一隻夜刃捕食者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。",
    [6102] = "使用馴獸棒馴服一隻巨翼惡梟。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。",
    [6103] = "與達納蘇斯塞納里奧區的祖卡斯特談話。",
    [6121] = "到月光林地去，與永夜港的德迪利特·星焰談話。",
    [6122] = "使用空的峭壁之泉取樣器在瀑布洞口獲得水樣本。$B$B將盛滿的峭壁之泉取樣器送到黑海岸奧伯丁的奧蘭達利亞·夜歌那裡。",
    [6123] = "收集5個地根草和12個月亮菇，把它們交給奧伯丁的奧蘭達利亞·夜歌，這樣她就可以製作解藥了。",
    [6124] = "對黑海岸的10頭生病的鹿使用動物醫療藥膏，以此來治療它們。從壁泉河到奧伯丁，直到最南端靠近梣谷的地區都有生病的鹿出沒。",
    [6125] = "回到達納蘇斯塞納里奧區的瑪斯雷·馭熊者那裡。",
    [6126] = "到月光林地去，與永夜港的德迪利特·星焰談話。",
    [6127] = "使用空的鬼霧峰取樣器在山頂取水樣。$B$B將盛滿的鬼霧峰取樣器送到貧瘠之地十字路口的圖加·符文圖騰那裡。",
    [6128] = "收集5個地根草和5個科多獸角，把它們交給十字路口的圖加·符文圖騰，這樣他就可以製作解藥了。",
    [6129] = "對貧瘠之地北部的10隻生病的瞪羚使用動物醫療藥膏，以此來治療它們。在穿過十字路口的那條東西走向的大路北面到處都是生病的蹬羚。",
    [6130] = "回到雷霆崖長者高地的圖拉克·符文圖騰那裡。",
    [6141] = "與淒涼之地的安東修士談話。",
    [6144] = "到幽暗城去與瓦里瑪薩斯談話。",
    [6145] = "返回東瘟疫之地，找到並殺死紅衣信差，拿到大十字軍的命令。$B$B把命令交給納薩諾斯·凋零者，並等待進一步的指示。",
    [6146] = "到瑪瑞斯農場東南方的提爾之手去，抵達那裡之後就咬一口爛蘋果。在血色十字軍偽裝的掩護下，把大十字軍的命令交給十字軍領主瓦德瑪爾。",
    [6147] = "帶著新情報返回納薩諾斯·凋零者那裡。",
    [6148] = "血色十字軍正在從提爾之手到斯坦索姆的路上巡邏，你可以在巡邏隊中找到聖者德米提雅和她的隨從，找到並殺死她。如果你成功了，就回到納薩諾斯·凋零者那裡去覆命。",
    [6163] = "到斯坦索姆去，殺掉吞嚥者拉姆斯登。把他的頭顱交給納薩諾斯。",
    [6402] = "前往暴風城的城門。和侍衛洛義談談，這樣他就會讓溫德索爾元帥知道你已抵達了。",
    [6403] = "跟隨雷吉納德·溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！",
    [6501] = "你必須尋遍世界以找到一種能恢復龍眼碎片的能量的生物。你對這種生物的唯一瞭解就是：他們確實存在。",
    [6502] = "你必須從達基薩斯將軍身上取回黑龍勇士之血。",
    [6566] = "聽索爾講話。",
    [6567] = "按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。",
    [6568] = "把雷克薩的證明交給西瘟疫之地的巫女米蘭達。",
    [6569] = "到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女米蘭達那裡。",
    [6570] = "去塵泥沼澤中的巨龍沼澤，找到艾博斯塔夫的洞穴。進入洞穴後帶上龍形護符，跟艾博斯塔夫交談。",
    [6582] = "找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給艾博斯塔夫。$B$B你可以在冬泉谷找到斯克利爾。",
    [6583] = "殺掉綠龍索姆努斯，把他的顱骨交給艾博斯塔夫。",
    [6584] = "諾茲多姆的孩子克魯納里斯在塔納利斯沙漠守衛著時光之穴。殺了牠，把牠的顱骨交給艾博斯塔夫。",
    [6585] = "到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給艾博斯塔夫。",
    [6601] = "看來這場猜謎遊戲就要結束了。你知道米蘭達為你製作的龍形護符在黑石塔裡面無法發揮作用，也許你應該去找雷克薩，將你的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下一步該怎麼做。",
    [6602] = "到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。",
    [6681] = "把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。$B$B你的智慧將在這次旅途中得到考驗。做好準備吧。",
    [6721] = "與多蘭納爾的達札拉談話。",
    [6722] = "與多蘭納爾的達札拉談話。",
    [6981] = "前往棘齒城尋找一個人，他能告訴你更多關於發光碎片的事。$B$B然後，將碎片送往被指示的地方。",
    [7028] = "為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。",
    [7029] = "在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。$B$B在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。$B$B治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕覆命。",
    [7041] = "在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。$B$B在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。$B$B治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞覆命。",
    [7044] = "找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。$B$B然後設法和塞雷布拉斯對話。",
    [7046] = "幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。$B$B當儀式完成之後再和他談談。",
    [7064] = "殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。",
    [7065] = "殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裡覆命。",
    [7066] = "到月光林地去找到雷姆洛斯，將生命之種交給他。",
    [7067] = "閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。",
    [7068] = "從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑪的尤塞爾奈。",
    [7070] = "從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃許。",
    [7201] = "到黑石深淵去取得10份元素精華。你應該在那些作戰傀儡和傀儡製造者身上找找，另外，薇薇安‧拉格雷也提到了一些有關元素生物的話題。",
    [7441] = "到厄運之槌去找到小鬼普希林。你可以使用任何手段從小鬼那裡得到埃斯托爾迪的咒術之書。$B$B找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裡。",
    [7461] = "你必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。一旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。$B$B進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰托塞德林王子。$B$B當任務完成之後，到庭院中去找辛德拉古靈。",
    [7462] = "返回圖書館去找到辛德拉的寶藏。拿取你的獎勵吧！",
    [7463] = "到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。",
    [7481] = "到厄運之槌去尋找卡里爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。",
    [7482] = "到厄運之槌去尋找泰謬斯·尋夢者。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。",
    [7488] = "把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。",
    [7489] = "把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。",
    [7490] = "將奧妮克希亞的頭顱交給奧格瑪的索爾。",
    [7491] = "在力量谷找到倫薩克。",
    [7492] = "和菲拉斯莫沙徹營地的塔羅·刺蹄談話。",
    [7493] = "屠龍者，還是一位經驗豐富的製皮師？你總是讓我驚嘆不已，英雄。我自愧不如。$B$B請接受我即將傳授給你的知識。如果你要消滅黑龍軍團的殘餘勢力，這些知識將會無比寶貴。$B$B用龍母的鱗片製作這件斗篷吧。它能保護你和你的盟友，抵禦黑石領主……奈法利安那熾熱的吐息。",
    [7494] = "和菲拉斯羽月要塞的拉托尼庫斯·月矛談話。",
    [7495] = "將奧妮克希亞的頭顱交給暴風城的伯瓦爾·弗塔根公爵。",
    [7496] = "在英雄谷找到瑪丁雷少校。",
    [7497] = "屠龍者，還是一位經驗豐富的製皮師？你總是讓我驚嘆不已，英雄。我自愧不如。$B$B請接受我即將傳授給你的知識。如果你要消滅黑龍軍團的殘餘勢力，這些知識將會無比寶貴。$B$B用龍母的鱗片製作這件斗篷吧。它能保護你和你的盟友，抵禦黑石領主……奈法利安那熾熱的吐息。",
    [7498] = "將這本典籍交給它的主人。",
    [7499] = "將這本典籍交給它的主人。",
    [7500] = "將這本典籍交給它的主人。",
    [7501] = "將這本典籍交給它的主人。",
    [7502] = "將這本典籍交給它的主人。",
    [7503] = "將這本典籍交給它的主人。",
    [7504] = "將這本典籍交給它的主人。",
    [7505] = "將這本典籍交給它的主人。",
    [7506] = "將這本典籍交給它的主人。",
    [7507] = "將《諾斯卓的屠龍技術綱要》還回圖書館。",
    [7508] = "把黯淡的精靈劍交給博學者萊德羅斯。",
    [7509] = "你必須設法讓奧妮克希亞對這把未淬火的的上古之刃噴射火焰。完成之後，撿起加熱過的上古之刃。你要注意的是，加熱過的上古之刃不會一直保持被加熱的狀態，時間非常緊迫。$B$B在把它給我拿回來之前的最後一步是殺掉那條龍，並將加熱過的上古之刃插入她的屍體中。$B$B完成這些之後，奎爾塞拉就是你的了。",
    [7562] = "與燃燒平原的莫蘇爾·召血者談話。",
    [7563] = "把30瓶狂暴野獸的血交給燃燒平原的莫蘇爾·召血者。",
    [7564] = "把血箱交給燃燒平原的戈瑟奇·邪眼。",
    [7604] = "如果你願意接受薩弗隆的設計圖，請將瑟銀兄弟會契約交給羅克圖斯·暗契。",
    [7623] = "從燃燒平原的戈瑟奇那裡購買暗影藥水。$B$B使用這種藥劑進入加德納爾，然後與魔王貝恩霍勒談話。",
    [7624] = "找到並殺死烏拉泰克，然後把叛徒之心交給加德納爾的魔王貝恩霍勒。",
    [7625] = "從烏爾丹那裡購買克索諾斯星塵，把它交給燃燒平原的戈瑟奇·邪眼。",
    [7626] = "把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。",
    [7627] = "把6份大塊魔光碎片和25塊黑鐵礦石交給燃燒平原的戈瑟奇·邪眼。",
    [7628] = "把35塊黑龍鱗片交給燃燒平原的戈瑟奇·邪眼。",
    [7629] = "把瓶中的小鬼帶到通靈學院的鍊金實驗室中。在小鬼製造出羊皮紙之後，把瓶子還給戈瑟奇·邪眼。",
    [7630] = "把3塊奧金錠交給燃燒平原的戈瑟奇·邪眼。",
    [7631] = "閱讀莫蘇爾的指南，並召喚出一匹克索諾斯恐懼戰馬，擊敗它，然後控制它的靈魂。",
    [7632] = "找到遠古石葉的主人。祝你好運，$N。這個世界是很大的。",
    [7634] = "費伍德森林的古樹哈斯塔特要求你帶回一塊成年藍龍的肌腱。",
    [7635] = "費伍德森林的古樹斯托瑪要求你帶給他一塊成年黑龍的肌腱。",
    [7636] = "你必須找到並幹掉下列4個惡魔：$B$B迷人的西蒙妮。$B$B瘋狂的克林弗蘭。$B$B屠殺者索倫諾爾。$B$B摧毀者阿托留斯。$B$B殺掉這些惡魔，然後回到費伍德森林的古樹瓦特魯斯那裡去。$B$B根據你背包中的石化樹皮來找到它們所在位置的線索。$B$B你必須獨自完成這個任務。",
    [7637] = "到鐵爐堡去找高階牧師洛漢，從他那裡拿到驅魔香爐。你需要捐贈150金幣來獲得它。",
    [7638] = "與暴風城教堂區的格雷森·沙東布瑞克公爵談話。",
    [7639] = "把驅魔香爐交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7640] = "使用驅魔香爐召喚恐懼谷中的靈魂。當你殺掉25個恐懼谷的靈魂之後，回到暴風城教堂區的格雷森·沙東布瑞克公爵那裡覆命。",
    [7641] = "與暴風城矮人區的格瑞曼德·艾爾默談話。",
    [7642] = "把40塊符文布、6塊奧金錠、10份阿薩斯之淚、5瓶斯坦索姆聖水和150枚金幣交給暴風城矮人區的格瑞曼德·艾爾默。",
    [7643] = "你需要特殊的飼料來餵養靈魂馬。南海鎮的梅麗德絲·卡爾森可以為你提供這樣的糧草。$B$B到菲拉斯的厄運之槌去，殺掉特迪斯·扭木，釋放上古聖馬之魂。用特殊的糧草餵養它，這樣可以安撫它的靈魂。最後，把奧金馬鎧交給它就可以完成祝福。",
    [7644] = "將受祝福的奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7645] = "把製作魔法糧草所需要的重要材料：20塊可口的魔法點心帶給希爾斯布萊德丘陵的梅麗德絲·卡爾森。據說銀色黎明會出售這種餅乾。$B$B你還需要給她50金幣來對她進行安撫。",
    [7646] = "把一塊艾澤拉斯鑽石和一塊原始黑鑽石交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7647] = "在通靈學院屍骨儲藏所地下室的中心使用預言水晶球。將你要審判的靈魂引領出來。將這些靈魂擊敗然後死亡騎士達克雷爾就將被召喚出來。將其擊敗然後獲得墮落戰馬的靈魂。$B$B把贖罪的戰馬之魂和受祝福的奧金馬鎧一起附在達克雷爾的墮落戰騎身上。",
    [7648] = "把奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。",
    [7703] = "找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。$B$B根據克羅卡斯所說的，「傳說」自稱是王子的精靈托塞德林從一名戈多克巨魔手中偷走了那件神器。",
    [7761] = "真是個愚蠢的獸人。看來你需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。$B$B你從信中獲知，達基薩斯將軍守衛著烙印。也許你應該就此進行更深入的調查。",
    [7785] = "查看重生之瓶，然後回到德米提恩那裡去。",
    [7786] = "如果你想要把逐風者桑德蘭從監牢裡釋放出來，你就必須找到左右2塊逐風者禁錮之顱，10塊源質錠，以及火焰之王的精華，把它們交給德米提恩。",
    [7787] = "把風吻之刃交給德米提恩。",
    [7877] = "返回圖書館去找到辛德拉的寶藏。拿取你的獎勵吧！",
    [8181] = "跟葉基亞談一談。",
    [8182] = "跟荊棘谷的莫托爾談話。",
    [8323] = "隱士奧泰爾希望你能帶給他10份加密的暮光文件。",
    [8410] = "為『觀風者』巴斯拉收集一份空氣樣本、一份火元素樣本、一份土元素樣本和一份水元素樣本。",
    [8412] = "將靈魂圖騰所需的材料交給捕風者巴斯拉。",
    [8921] = "將1個精密奧金轉換器、4份強效不滅精華、10瓶石鱗魚油，25份火山灰和40金交給在加基森的莫克斯·施法者。",
    [8922] = "將密封的鮮血採樣瓶帶到塔納利斯的加基森，交給莫克斯·施法者。",
    [8923] = "將密封的毒液罐交給在加基森的莫克斯·施法者。",
    [8924] = "前往東瘟疫之地，在無形的不死族附近使用外膜蒸餾器收集12個希利蘇斯燒焦的外膜、12個冬泉谷冰凍的外膜和12個東瘟疫之地穩定的外膜。將它們和外膜蒸餾器一起交給在加基森的莫克斯·施法者。",
    [8925] = "去燃燒平原找到麥格瑪·博克王，取得他的岩漿之核帶給在加基森的莫克斯·施法者。",
    [8928] = "前往冬泉谷南方的暗語峽谷入口，向住在洞穴裡的小鬼買下一把惡魔元素魔棒，再回到加基森的莫克斯·施法者那裡。",
    [8929] = "在斯坦索姆的入口使用超空間靈體顯像機並和安希恩·哈莫的鬼魂談談。",
    [8930] = "在斯坦索姆的入口使用超空間靈體顯像機並和安希恩·哈莫的鬼魂談談。",
    [8945] = "前往斯坦索姆從瑞文戴爾男爵那裡救出亞希達·哈莫。",
    [8946] = "將亞希達的小墜子帶給東溫疫之地的安希恩·哈莫。",
    [8947] = "將3塊黑鐵錠，20塊魔化皮，3塊月布和4塊熟化毛皮帶給東溫疫之地的安希恩·哈莫。",
    [8948] = "將不完整的挑釁旗幟帶到厄運之槌的圖書館給法琳·樹形者。",
    [8949] = "從厄運之錘或黑石塔的巨魔身上收集25個巨魔戰爭串珠再回到厄運之錘圖書館找法琳·樹形者。",
    [8950] = "將以下的物品帶給厄運之槌的法琳·樹形者：1份嘲弄幽靈精華，4個黑暗符文和8個大塊魔光碎片。",
    [8960] = "到黑石山並使用超空間靈體顯像機，去黑石塔附近尋找布德利。",
    [8961] = "收集伊森迪奧斯的煤渣，艾博希爾的煤炭和辛德爾的煤渣，並帶著神聖火盆回到黑石山找布德利。",
    [8962] = "取得德魯伊的遺體，再回到黑石山找布德利。",
    [8963] = "取得星風村聖物，再回到黑石山找布德利。",
    [8964] = "取得光亮的狂熱之劍，再回到黑石山找布德利。",
    [8965] = "取得流放者的靈魂灰燼，再回到黑石山找布德利。",
    [8966] = "使用召喚火盆來召喚莫爾·灰蹄的靈魂並殺了他。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的布德利那裡。",
    [8967] = "使用召喚火盆來召喚依薩利恩的靈魂並殺了她。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的布德利那裡。",
    [8968] = "使用召喚火盆來召喚賈林和索索斯並殺了他們。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的布德利那裡。",
    [8969] = "使用召喚火盆召喚科爾莫克的靈魂並殺了他。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的布德利那裡。",
    [8970] = "在斯塔沙茲納迦身上收集20份血巨藻再回到黑石山的布德利那裡。",
    [8977] = "將超空間靈體顯像機帶給鐵爐堡的德莉娜。",
    [8978] = "帶著超空間靈體顯像機回到奧格瑪的莫克瓦那裡。",
    [8985] = "取得星風村聖物，再回到黑石山找布德利。",
    [8986] = "取得德魯伊的遺體，再回到黑石山找布德利。",
    [8987] = "取得光亮的狂熱之劍，再回到黑石山找布德利。",
    [8988] = "取得流放者的靈魂灰燼，再回到黑石山找布德利。",
    [8989] = "使用召喚火盆召喚莫爾·灰蹄的靈魂並殺了他。帶著重新組合的瓦薩拉克護符和召喚火盆回到黑石山的布德利那裡。",
    [8990] = "使用召喚火盆召喚依薩利恩的靈魂並殺了她。帶著重新組合的瓦薩拉克護符和召喚火盆回到黑石山的布德利那裡。",
    [8991] = "使用召喚火盆召喚賈林和索索斯並殺了他們。帶著重新組合的瓦薩拉克護符和召喚火盆回到黑石山的布德利那裡。",
    [8992] = "使用召喚火盆召喚科爾莫克的靈魂並殺了他。帶著重新組合的瓦薩拉克護符和召喚火盆回到黑石山的布德利那裡。",
    [8994] = "收集40個黑石護腕和1份超級能量精煉藥水。把它們帶給黑石山上的布德利。",
    [8995] = "用召喚火盆召喚出瓦薩拉克。殺了他，在他的屍體上使用瓦薩拉克的護符。然後，將瓦薩拉克的護符還給瓦薩拉克的靈魂。",
    [8996] = "回到黑石山的布德利那裡並將召喚火盆交給他。",
    [8997] = "與鐵爐堡王座廳的德莉娜交談。",
    [9015] = "前往黑石深淵的秩序競技場並在你被裁決者格里斯通宣判時將挑釁旗幟放在它的中央。殺死瑟爾倫和他的戰士們，再帶著第一塊瓦薩拉克護符回到東瘟疫之地的安希恩·哈莫那裡。",
    [9362] = "為大法師克希雷姆取得多彩貝殼。大法師就住在艾薩拉懸崖頂的一座哨塔裡。",
    [9364] = "對艾薩拉的惡鞭者施放變形術並殺死幾秒後出現的複製物。等你殺了50個變形複製，再回去找艾薩拉的大法師克希雷姆。",
    [78261] = "在影牙城堡中尋找澤索司號角，接著再回到 C 於焚木村附近的密件藏匿處。你必須獨自一人完成任務。",
    [78676] = "在血色修道院中尋找伯絲卡之眼，接著再回到 C 於焚木村附近的密件藏匿處。你必須獨自一人完成任務。",
    [79007] = "燒灼的紙條殘骸是你唯一的線索。",
    [79008] = "燒灼的紙條殘骸是你唯一的線索。",
    [79192] = "你將木板上的紙條撕了下來，閱讀上面的草寫文字。",
    [79229] = "到淒涼之地找清楚遭掠營地內情的人。",
    [79235] = "找到其中一個淒涼之地掠奪者。",
    [79236] = "將櫻桃酒交給藏寶海灣的托卡，然後聽她說完剩下的故事。",
    [79242] = "在阿拉希高地海岸找到伊拉里‧暮羽，然後找出她藏贓物的箱子。",
    [79358] = "為阿拉希高地的維里克‧雷鎚收集5個扭曲火焰圖騰、5個扭曲大地圖騰、5個扭曲空氣圖騰和5個扭曲水之圖騰。",
