    [96381] = "進入奧卡茲監獄並殺死15個斯塔莎茲士兵、8個斯塔莎茲女巫師，並將卡薩絲小姐的頭顱帶去給蘇利‧麥拉利。",
    [96435] = "把術士骨頭丟到軟泥池附近的骨堆上。",
    [96770] = "殺死巫醫祖穆拉恩，將祖穆拉恩的頭顱帶去給達拉然的大法師朗達拉克。",
    [96771] = "前往克羅多克要塞，並殺死薩爾凡‧月影。",
    [96772] = "在奧卡茲監獄的深處找回札菈的日記。",
    [96774] = "從沉沒之城取回遠古古拉巴什塑像。",
    [96775] = "殺死巫醫祖穆拉恩，將祖穆拉恩的頭顱帶去給莫高雷的瑪庫可。",
    [96776] = "從瑪拉頓取走名為安希的烈光的水晶。",
    [96779] = "在希爾斯布萊德丘陵的敦霍爾德城堡中找到並擊殺湯瑪斯領主。然後回去找麥洛克斯。",
    [96781] = "對巴爾頓使用偷竊，偷取巴爾頓的偵察報告。然後，將報告交給拉文霍德莊園的麥洛克斯。",
    [96782] = "在奧特蘭克的廢墟中找到匹瑞諾德家族之刃和匹瑞諾德皇家禦盾。然後將它們交給麥洛克斯。",
    [96783] = "從諾斯弗德農場偷取辛迪加制服，以潛入激流堡。",
    [96784] = "偽裝成辛迪加的成員，在激流堡中找到知道這筆秘密交易的人。",
    [96785] = "在激流堡中找到能說服安娜斯塔西亞透露秘密交易細節的東西。",
    [96786] = "破壞這筆秘密交易，奪走要交易給辛迪加的物品。然後回到拉文霍德莊園的麥洛克斯那裡。",
    [96800] = "到血色修道院取回《符文大師的失傳魔法》。",
    [96930] = "回去找好奇的烏鴉。",
    [96931] = "觸碰俯瞰祥和育所橋上的烏鴉肖像，呼喚荒野神靈傑瑞曼。",
    [96939] = "與荒野神靈馬羅希斯交談。",
    [96964] = "與荒野之神瑞納拉德交談。",
    [97022] = "與班達利昂要塞的丹妮莎‧莫爾交談。",
    [97130] = "從沉沒之城取回遠古古拉巴什塑像。",
    [97168] = "如果你願意幫助鐵爐堡的伊德倫‧破颶者，就將一塊艾澤拉斯鑽石和一塊原始黑鑽石交給他。",
    [97169] = "在通靈學院大骨窖地下室的中心使用預言水晶球。這麼做會召喚出你必須與之戰鬥的靈魂。擊敗這些靈魂後將會召喚出死亡騎士達克雷爾；擊敗他。$B$B把達克雷爾的頭顱交給鐵爐堡荒棄洞穴裡的伊德倫‧破颶者。",
    [97173] = "從黑喉要塞取回黑喉儀式圖騰。",
    [97174] = "在提里斯法林地的班達利昂要塞與丹妮莎‧莫爾交談。",
    [97175] = "到奧格瑪去找高階牧師薩尤斯，從他那裡拿到驅魔香爐。你需要捐贈150金幣才能得到它。",
    [97176] = "使用驅魔香爐驅逐恐懼谷中受折磨的靈魂。消滅25個恐懼谷之靈後，回到提里斯法林地班達利昂要塞的丹妮莎‧莫爾那裡。",
    [97177] = "把驅魔香爐還給提里斯法林地班達利昂要塞的丹妮莎‧莫爾。",
    [97178] = "與希爾斯布萊德丘陵塔倫米爾村的奧特交談。",
    [97179] = "把40塊符文布、6塊奧金錠、10株阿薩斯之淚、5瓶斯坦索姆聖水和150金幣交給希爾斯布萊德丘陵的奧特。",
    [97180] = "把奧金馬鎧拿給班達利昂要塞的丹妮莎‧莫爾檢查。",
    [97182] = "取得用來餵食靈魂戰馬的特製馬飼料。東瘟疫之地的納薩諾斯‧凋零者或許能提供這種飼料。$B$B前往菲拉斯的厄運之槌並殺死特迪斯‧扭木。這麼做會釋放上古聖馬之魂。餵牠吃特製馬飼料來安撫牠。$B$B最後，把奧金馬鎧交給牠，並祈禱牠願意賜予所需的祝福。",
    [97183] = "帶著受祝福的奧金馬鎧回到提里斯法林地班達利昂要塞的丹妮莎‧莫爾那裡。",
    [97184] = "把一顆艾澤拉斯鑽石和一顆無瑕的黑鑽石帶給提里斯法林地班達利昂要塞的丹妮莎‧莫爾。",
    [97185] = "在通靈學院大骨窖地下室的中心使用預言水晶球。這麼做會召喚出你必須審判的靈魂。擊敗這些靈魂後將會召喚出死亡騎士達克雷爾。擊敗他，並奪回陣亡戰駒失落的靈魂。$B$B把懲戒之靈和受祝福的附魔馬鎧交給達克雷爾的陣亡戰駒。",
    [97186] = "為東瘟疫之地的納薩諾斯‧凋零者取得20塊濃縮瑪納餅乾。銀色黎明是這種餅乾唯一的供應者。你還需要付給凋零者50金幣作為他的酬勞。",
    [97197] = "為莫高雷的阿菈娜‧雷暴行者從黑石深淵取回火源之界碎片。",
    [97198] = "從黑喉要塞取回黑喉儀式圖騰。",
    [97243] = "前往風莓低地的烈焰聖殿，將眠焰火炬交給歐拉里安‧迅燃。",
    [97244] = "到風莓低地殺死天空祭司法拉迪爾並收集法拉迪爾的心臟。",
    [97245] = "到申德高地找到庫拉瑪的居所，在戰鬥中擊敗它。取得勝利後，將庫拉瑪的面具交給風莓低地的歐拉里安‧迅燃。",
    [97250] = "在通往塵泥沼澤的邊境殺死進逼貧瘠之地的聯盟士兵，之後回到陶拉祖營地找步兵勞格瑪。",
    [97257] = "等待歐拉里安開始在祭品火盆進行儀式，並聽從他的指示。",
    [97288] = "將可憎頭顱交給幽暗城裡的大藥劑師法拉尼爾。",
    [97289] = "到幽暗城，把男爵的頭放在歐斯瑪的遺體旁。",
    [97290] = "把你發現的事說給幽暗城的大藥劑師法拉尼爾聽。",
    [97291] = "幫幽暗城的大藥劑師法拉尼爾向貿易區的塔文‧格瑞斯特收集劇毒顱帽，在草藥學訓練師附近收集灼蝕草，以及向盜賊區的毒藥商購買苦楚精華。",
    [97292] = "幫大藥劑師法拉尼爾把嘶鳴藥水注射到歐斯瑪遺骸上的系統管道中。",
    [97327] = "進入黑喉要塞，幫艾薩拉埃達拉斯廢墟的艾卡爾取回5個黑喉袋子。",
    [97411] = "取得15滴希利蘇斯毒液樣本，同時將20枚金幣和一套光鑄護腕一起交給奧格瑪的莫克瓦。",
    [97412] = "把一條光鑄腰帶和一副光鑄護手交給奧格瑪的莫克瓦。",
    [97413] = "帶著一套光鑄長靴、光鑄腿鎧和光鑄護肩，回到奧格瑪的莫克瓦那裡。",
    [97447] = "取得15滴冬泉血滴樣本，同時將20枚金幣和一套元素束腕一起交給鐵爐堡的德莉娜。",
    [97448] = "把一條元素束帶和一副元素護手交給鐵爐堡的德莉娜。",
    [97449] = "帶著一套元素長靴、元素短裙和元素肩鎧，回到鐵爐堡的德莉娜那裡。",
    [98094] = "高級執行官達薩利亞要你把新命令拿到丹加洛克外，並交給塔倫米爾南方的亡靈哨兵馬索吉。",
    [98095] = "亡靈哨兵馬索吉要你在希爾斯布萊德丘陵附近的山峰上放置三個藥劑師瓶子，然後再回去找他。",
    [98096] = "到艾薩拉的塔倫迪斯營地找指揮官真歌，然後詢問科爾達拉·日刃的下落。",
    [98298] = "將6個狼人碎塊帶去給瑟伯切爾的達拉爾‧織曦者。",
    [98299] = "為瑟伯切爾的達拉爾‧織曦者殺死5個病怏怏的難民和5個憔悴的難民。",
    [98325] = "與軍官高圖斯交談來加入卡加斯遠征軍。",
    [98340] = "與月光林地永夜港的德迪利特‧星焰交談。",
    [98341] = "到月光林地的南部找賽利南的化身，向它學習關於風裔獵豹的知識。",
    [98342] = "從怒風獸穴取回尖牙聖物、利爪聖物和寂靜暗影聖物，然後交給巨豹之靈。",
    [98362] = "回到雷霆崖，與長者高地的圖拉克‧符文圖騰談話。",
    [98393] = "與月光林地永夜港的德迪利特‧星焰交談。",
    [98394] = "到月光林地的南部找巨豹之靈，向它學習關於獵豹的知識。",
    [98396] = "從怒風獸穴取回尖牙聖物、利爪聖物和寂靜暗影聖物，然後交給巨豹之靈。",
    [98397] = "回到達納蘇斯，與塞納里奧區的瑪斯雷‧馭熊者談話。",
    [98404] = "從怒風獸穴取回尖牙聖物、利爪聖物和寂靜暗影聖物，然後交給賽利南的化身。",
    [98405] = "到月光林地的南部找巨豹之靈，向它學習關於獵豹的知識。",
    [98447] = "為夜色鎮的希拉·沃寧迪查明烏鴉嶺瓦勒家族鬼魂出沒的原因。",
    [98512] = "在申德高地殺死10個奧拉凱斯刺客。",
    [98517] = "向微風島的賽莎莉亞‧天步或阿爾諾‧烈風報到，繼續你的薩滿訓練。$B$B你可以在雷霆崖西北方、莫高雷的天空守望者高原搭乘停靠在那裡的天刃運輸艇返回微風島。",
    [98731] = "到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。",
    [98738] = "到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。",
    [98739] = "與德迪利特交談。",
    [98830] = "將托塞德林的破碎戰刃交給厄運之槌的辛德拉古靈。",
    [99257] = "殺死一個破舊水晶塔保衛者並取回它枯竭的水晶之心，然後將其帶給申德拉斯神殿中的歷史學家畢拉薩斯。",
    [99258] = "把耗竭的水晶之心扔進不穩定的法力裂隙。帶著成功或失敗的證明，回到申德拉斯神殿裡的歷史學家比拉克薩斯那裡。",
    [99260] = "和瓦拉納爾的伊拉德林‧和風交談。",
    [99435] = "跟隨雷吉納德‧溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！",
    [99670] = "回去祥和育所找傑瑞曼。",
}
